SELECT CASE WHEN unit_price >= 370 THEN 'high' WHEN unit_price >= 110 THEN 'mid' ELSE 'low' END AS unit_price_bucket, CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END AS quantity_bucket, MIN(unit_price) AS min_unit_price, ROUND(STDDEV(quantity), 2) AS stddev_quantity, MAX(quantity) - MIN(quantity) AS quantity_range FROM order_items GROUP BY CASE WHEN unit_price >= 370 THEN 'high' WHEN unit_price >= 110 THEN 'mid' ELSE 'low' END, CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 4 THEN 'mid' ELSE 'low' END HAVING MAX(unit_price) > 170 ORDER BY quantity_bucket, unit_price_bucket LIMIT 5;
